namespace GrapSolution.Domain;

public abstract class Entity { public string Id { get; set; } = Guid.NewGuid().ToString(); public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public sealed class RuleException(string code, string message, int status = 409, int? version = null, bool persist = false) : Exception(message)
{ public string Code { get; } = code; public int Status { get; } = status; public int? CurrentVersion { get; } = version; public bool Persist { get; } = persist; }
public static class Roles
{
    public const string Customer = "Customer", Driver = "Driver", Reviewer = "DriverReviewer", Dispatcher = "Dispatcher", Support = "SupportAgent", Finance = "FinanceOperator", Approver = "FinanceApprover", Operations = "OperationsAdmin", Security = "SecurityAdmin";
    public static readonly string[] Staff = [Reviewer, Dispatcher, Support, Finance, Approver, Operations, Security];
}
public static class RideStates
{
    public static readonly string[] Active = ["SEARCHING", "ASSIGNED", "DRIVER_ARRIVED", "IN_PROGRESS"];
    public static bool IsActive(string state) => Active.Contains(state);
    public static void Require(string state, params string[] allowed) { if (!allowed.Contains(state)) throw new RuleException("INVALID_RIDE_STATE", "Thao tác không hợp lệ với trạng thái chuyến hiện tại."); }
}
public record GeoPoint(double Latitude, double Longitude, string Address)
{
    public void Validate() { if (!double.IsFinite(Latitude) || !double.IsFinite(Longitude) || Latitude is < -90 or > 90 || Longitude is < -180 or > 180 || string.IsNullOrWhiteSpace(Address) || Address.Length > 500) throw new RuleException("INVALID_COORDINATES", "Vị trí hoặc địa chỉ không hợp lệ.", 400); }
    public double DistanceTo(GeoPoint other) { const double r = Math.PI / 180; var a = Math.Pow(Math.Sin((other.Latitude - Latitude) * r / 2), 2) + Math.Cos(Latitude * r) * Math.Cos(other.Latitude * r) * Math.Pow(Math.Sin((other.Longitude - Longitude) * r / 2), 2); return 6371000 * 2 * Math.Atan2(Math.Sqrt(a), Math.Sqrt(1 - a)); }
}
public sealed class User : Entity { public string Phone { get; set; } = ""; public string Name { get; set; } = ""; public string Role { get; set; } = Roles.Customer; public string ZoneId { get; set; } = "hcm"; public string Status { get; set; } = "ACTIVE"; public string? Email { get; set; } public int Version { get; set; } = 1; }
public sealed class Session : Entity { public string UserId { get; set; } = ""; public string DeviceId { get; set; } = ""; public string RefreshHash { get; set; } = ""; public string Family { get; set; } = Guid.NewGuid().ToString(); public DateTime ExpiresAt { get; set; } = DateTime.UtcNow.AddDays(30); public DateTime? RevokedAt { get; set; } }
public sealed class OtpChallenge : Entity { public string Phone { get; set; } = ""; public string AppType { get; set; } = "customer"; public string CodeHmac { get; set; } = ""; public int Attempts { get; set; } public DateTime ExpiresAt { get; set; } = DateTime.UtcNow.AddMinutes(3); public DateTime? ConsumedAt { get; set; } }
public sealed class Driver : Entity
{
    public string UserId { get; set; } = ""; public string ReviewStatus { get; set; } = "DRAFT"; public string ServiceTypeCode { get; set; } = "BIKE"; public string Plate { get; set; } = ""; public string Vehicle { get; set; } = ""; public string Color { get; set; } = ""; public string ZoneId { get; set; } = "hcm"; public bool Online { get; set; } public bool OfflineAfterRide { get; set; } public string? ActiveSessionId { get; set; } public DateTime? HeartbeatAt { get; set; } public double Latitude { get; set; } public double Longitude { get; set; } public double Accuracy { get; set; } = 20; public long LocationSequence { get; set; } public DateTime? LocationAt { get; set; } public DateTime? DocumentsExpireAt { get; set; } public string? ReviewReason { get; set; } public decimal Rating { get; set; } = 5; public int Version { get; set; } = 1;
}
public sealed class DriverDocument : Entity { public string DriverId { get; set; } = ""; public string Type { get; set; } = ""; public string FileId { get; set; } = ""; public string? ReviewReason { get; set; } public string Status { get; set; } = "PENDING_REVIEW"; public DateTime ExpiresAt { get; set; } public int Version { get; set; } = 1; }
public sealed class ServiceZone : Entity { public string Name { get; set; } = "TP. Hồ Chí Minh"; public string PolygonJson { get; set; } = "[]"; public bool Active { get; set; } = true; public int Version { get; set; } = 1; }
public sealed class FarePolicy : Entity
{
    public string ZoneId { get; set; } = "hcm"; public string ServiceTypeCode { get; set; } = "BIKE"; public string Name { get; set; } = "GrapBike"; public int Version { get; set; } = 1; public string Status { get; set; } = "DRAFT"; public long BaseFare { get; set; } = 12000; public long PerKm { get; set; } = 4500; public long PerMinute { get; set; } = 300; public long MinimumFare { get; set; } = 15000; public long ServiceFee { get; set; } = 2000; public decimal CommissionRate { get; set; } = 0.2m; public DateTime EffectiveFrom { get; set; } = DateTime.UtcNow; public string CreatedBy { get; set; } = "";
    public FareBreakdown Calculate(int meters, int seconds) { if (meters <= 0 || seconds <= 0) throw new RuleException("ROUTE_UNAVAILABLE", "Không có tuyến đường hợp lệ.", 422); var distance = (long)decimal.Ceiling(meters / 1000m * PerKm); var duration = (long)decimal.Ceiling(seconds / 60m * PerMinute); var transport = Math.Max(MinimumFare, BaseFare + distance + duration); return new(BaseFare, distance, duration, ServiceFee, transport + ServiceFee, transport + ServiceFee, (long)decimal.Round(transport * CommissionRate, 0, MidpointRounding.AwayFromZero)); }
}
public record FareBreakdown(long BaseFare, long DistanceFare, long DurationFare, long ServiceFee, long GrossFare, long CustomerPayable, long PlatformCommission, long Discount = 0, long ApprovedExtras = 0, long TaxComponent = 0, string Currency = "VND");
public sealed class Quote : Entity { public string CustomerId { get; set; } = ""; public GeoPoint Pickup { get; set; } = new(0, 0, ""); public GeoPoint Dropoff { get; set; } = new(0, 0, ""); public string ServiceTypeCode { get; set; } = "BIKE"; public string ZoneId { get; set; } = "hcm"; public string FarePolicyId { get; set; } = ""; public int FarePolicyVersion { get; set; } public FareBreakdown Fare { get; set; } = new(0, 0, 0, 0, 0, 0, 0); public int DistanceMeters { get; set; } public int DurationSeconds { get; set; } public string RouteSource { get; set; } = ""; public string? RouteGeometry { get; set; } public DateTime ExpiresAt { get; set; } = DateTime.UtcNow.AddSeconds(120); public string? ConsumedRideId { get; set; } }
public sealed class Ride : Entity
{
    public string Code { get; set; } = "GR" + DateTime.UtcNow.ToString("yyMMdd") + Guid.NewGuid().ToString("N")[..6].ToUpperInvariant(); public string CustomerId { get; set; } = ""; public string? DriverId { get; set; } public string QuoteId { get; set; } = ""; public string ZoneId { get; set; } = "hcm"; public string ServiceTypeCode { get; set; } = "BIKE"; public string Status { get; set; } = "SEARCHING"; public string PickupNote { get; set; } = ""; public GeoPoint Pickup { get; set; } = new(0, 0, ""); public GeoPoint Dropoff { get; set; } = new(0, 0, ""); public FareBreakdown Fare { get; set; } = new(0, 0, 0, 0, 0, 0, 0); public string PinHmac { get; set; } = ""; public string CustomerPinProtected { get; set; } = ""; public int PinAttempts { get; set; } public int Version { get; set; } = 1; public DateTime DeadlineAt { get; set; } = DateTime.UtcNow.AddSeconds(120); public DateTime? ArrivedAt { get; set; } public DateTime? EndedAt { get; set; }
    public void CheckVersion(int expected) { if (Version != expected) throw new RuleException("VERSION_CONFLICT", "Trạng thái đã thay đổi, vui lòng tải lại.", 409, Version); }
    public void Change(string state) { Status = state; Version++; if (!RideStates.IsActive(state)) EndedAt = DateTime.UtcNow; }
}
