public sealed class Journal : Entity { public string OperationKey { get; set; } = ""; public string RideId { get; set; } = ""; public string Description { get; set; } = ""; public List<LedgerEntry> Entries { get; set; } = []; public void Validate() { if (Entries.Count < 2 || Entries.Any(e => e.Debit < 0 || e.Credit < 0 || (e.Debit > 0 && e.Credit > 0)) || Entries.Sum(e => e.Debit) != Entries.Sum(e => e.Credit)) throw new RuleException("UNBALANCED_JOURNAL", "Bút toán không cân bằng.", 422); } }
